// "IA" de mentira: classifica pela presenca de palavras-chave.
// Simula o contrato da API real: { id, categoria_sugerida, confianca, modelo, justificativa }
const palavras = {
  buraco:     ['buraco', 'asfalto', 'pavimento', 'cratera', 'remendo'],
  iluminacao: ['poste', 'lampada', 'luz', 'iluminacao', 'apagado', 'escuro'],
  descarte:   ['lixo', 'entulho', 'descarte', 'sujeira', 'residuo', 'sofa'],
  calcada:    ['calcada', 'passeio', 'acessibilidade', 'rampa', 'piso', 'cadeirante'],
  mobiliario: ['banco', 'placa', 'ponto de onibus', 'lixeira', 'abrigo', 'mobiliario'],
};

const semAcento = (t) => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

return $input.all().map((item) => {
  const b = item.json.body ?? item.json;
  const texto = semAcento(`${b.titulo} ${b.descricao}`);

  let melhor = null, melhorPontos = 0, achadas = [];
  for (const [categoria, lista] of Object.entries(palavras)) {
    const encontradas = lista.filter(p => texto.includes(p));
    if (encontradas.length > melhorPontos) {
      melhor = categoria; melhorPontos = encontradas.length; achadas = encontradas;
    }
  }

  const categoriaSugerida = melhor ?? b.categoria;
  let confianca = 0.5;
  if (melhor && melhor === b.categoria) confianca = 0.92;
  else if (melhor) confianca = 0.65;

  return {
    json: {
      id: b.id,
      categoria_sugerida: categoriaSugerida,
      confianca,
      modelo: 'mock-palavras-chave-v1',
      justificativa: achadas.length ? `palavras encontradas: ${achadas.join(', ')}` : 'nenhuma palavra-chave encontrada',
    },
  };
});
